'use strict';
const D=JSON.parse(document.getElementById('report-data').textContent),all=D.rows,$=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(r,k)=>Number(r[k])||0,ageLabels={'0-30':'0–30 天','31-90':'31–90 天','91-180':'91–180 天','181-365':'181–365 天','>365':'超过 365 天'};
const defs=[
 {key:'surface_scope',label:'技术范围'},{key:'assignees',label:'GitHub assignee',multi:true,empty:'未设置'},
 {key:'milestone',label:'目标 Milestone',empty:'未设置'},{key:'impact_types',label:'问题表现',multi:true},
 {key:'current_progress',label:'公开进展'},{key:'classification_confidence',label:'分类证据状态'},{key:'public_record_status',label:'记录性质'},{key:'pr_stage',label:'关闭引用 PR 阶段',multi:true},
 {key:'repair_pr_status',label:'关闭引用 PR 状态'},{key:'pr_relation',label:'PR 引用关系'},
 {key:'owner_status',label:'负责人字段状态'},{key:'primary_blocker',label:'公开阻塞线索'},
 {key:'closure_status',label:'关闭审查状态'},{key:'closure_configuration_status',label:'验证配置核对'},{key:'closure_reasons',label:'关闭候选原因',multi:true},
 {key:'verification_status',label:'验证线索状态'},{key:'classification_review',label:'人工核查状态'},
 {key:'repro_materials',label:'已提取复现材料',multi:true},{key:'repro_gaps',label:'待补充材料线索',multi:true},
 {key:'discovery_channels',label:'发现渠道',multi:true},{key:'age_bucket',label:'存在时间',order:Object.keys(ageLabels)},
 {key:'hardware_in_title',label:'硬件线索',multi:true},{key:'os_in_title',label:'操作系统',multi:true},
 {key:'release_in_title',label:'版本线索',multi:true},{key:'labels_raw',label:'原始标签',multi:true},
 {key:'test_paths',label:'测试入口',multi:true},{key:'source_paths',label:'显式源码路径',multi:true}
];
const defMap=new Map(defs.map(d=>[d.key,d])),rowById=new Map(all.map(r=>[r.issue,r]));
const values=(r,key)=>{const d=defMap.get(key),raw=String(r[key]||'');if(d?.multi){const tokens=[...new Set(raw.split(/[;；]/).map(s=>s.trim()).filter(Boolean))];return tokens.length?tokens:['__empty__'];}return [raw||'__empty__'];};
const tokens=new Map(all.map(r=>[r.issue,new Map(defs.map(d=>[d.key,new Set(values(r,d.key))]))]));
const searchIndex=new Map(all.map(r=>[r.issue,Object.entries(r).filter(([k])=>k!=='linked_prs').map(([,v])=>String(v)).join(' ').toLowerCase()+' '+r.linked_prs.map(p=>{const pr=D.prs[p.id];return pr.repository+'#'+pr.number+' '+pr.title;}).join(' ').toLowerCase()]));
const linkedFor=r=>r.linked_prs.map(p=>({...D.prs[p.id],explicit_fix_reference:p.explicit_fix_reference}));
const hasFix=(r,test)=>r.linked_prs.some(ref=>ref.explicit_fix_reference&&test(D.prs[ref.id]));
const queues=[
 {id:'closure',group:'关闭审查',title:'全部关闭审查候选',hint:'按 issue 去重，展示依据与未完成事项',test:r=>r.closure_candidate==='1'},
 {id:'closure-ready',group:'关闭审查',title:'优先审查关闭',hint:'清单已有处理证据，未提取到明确剩余事项',test:r=>r.closure_status==='优先审查关闭'},
 {id:'closure-confirm',group:'关闭审查',title:'需要补充确认',hint:'核对版本、覆盖和处理去向',test:r=>r.closure_status==='需要补充确认'},
 {id:'closure-blocked',group:'关闭审查',title:'存在未完成事项',hint:'保留失败、目标分支与 skip 后续工作',test:r=>r.closure_status==='存在未完成事项'},
 {id:'recent',group:'排查问题',title:'最近 30 天创建',hint:'仍未关闭的近期记录',test:r=>n(r,'age_days')<=30},
 {id:'regression',group:'排查问题',title:'带 regression 标签',hint:'核对通过与失败版本',test:r=>r.regression_label==='1'},
 {id:'expectation',group:'排查问题',title:'测试预期需核对',hint:'Unexpected success / xfail',test:r=>values(r,'impact_types').includes('测试预期需核对')},
 {id:'ci',group:'推进修复',title:'关闭引用 PR 的 CI 失败',hint:'检查失败仍需核对原因',test:r=>r.pr_ci_failed==='1'},
 {id:'review',group:'推进修复',title:'审查需修改 / 待审查',hint:'只统计明确关闭引用',test:r=>hasFix(r,p=>p.state==='OPEN'&&['CHANGES_REQUESTED','REVIEW_REQUIRED'].includes(p.review))},
 {id:'conflict',group:'推进修复',title:'关闭引用 PR 存在冲突',hint:'GitHub mergeable = CONFLICTING',test:r=>hasFix(r,p=>p.state==='OPEN'&&p.mergeable==='CONFLICTING')},
 {id:'skipped',group:'恢复与验证',title:'带 skipped 标签',hint:'核对跳过条件与恢复验证',test:r=>r.skipped_label==='1'},
 {id:'merged',group:'恢复与验证',title:'关闭引用已合并，Issue 仍 Open',hint:'核对剩余工作与验证证据',test:r=>r.repair_pr_status==='明确关闭引用 PR 已合并'},
 {id:'dependency',group:'恢复与验证',title:'存在依赖线索',hint:'依赖标签或最近人工讨论',test:r=>r.primary_blocker==='存在依赖线索'}
];
const qualityDefs=[
 {id:'hasTest',title:'有测试入口',hint:'已从公开正文提取',test:r=>Boolean(r.test_paths),filter:['repro_materials','有测试入口']},
 {id:'hasCode',title:'有代码线索',hint:'原始代码块或正文代码行',test:r=>r.repro_code_present==='1',filter:['repro_materials','有代码片段线索']},
 {id:'hasVersion',title:'有报告版本',hint:'不是最近验证版本',test:r=>Boolean(r.reported_pytorch_version),filter:['repro_materials','有报告版本']},
 {id:'unknownImpact',title:'影响待定位',hint:'不强行推断失败类型',test:r=>r.impact_types==='影响未知',filter:['impact_types','影响未知']},
 {id:'unknownScope',title:'技术范围待定位',hint:'缺少明确技术层证据',test:r=>r.surface_scope==='未知',filter:['surface_scope','未知']},
 {id:'candidates',title:'有验证评论线索',hint:'需核对版本、环境与结果',test:r=>r.verification_status==='有待核查的人工评论线索',filter:['verification_status','有待核查的人工评论线索']},
 {id:'reviewed',title:'有人工核查记录',hint:'保留核查人、日期和依据',test:r=>r.classification_review==='有人工核查记录',filter:['classification_review','有人工核查记录']},
 {id:'verified',title:'验证记录已人工核查',hint:'明确版本、硬件、结果与证据',test:r=>r.verification_status==='已人工核查验证记录',filter:['verification_status','已人工核查验证记录']}
];
const closureRank={'优先审查关闭':0,'需要补充确认':1,'存在未完成事项':2,'暂无关闭候选依据':3};
const state={view:'developer',queue:'',query:'',filters:{},sort:'updated-desc',page:1,size:10};
const universe=new Map(),totals=new Map(),queueCounts=new Map(queues.map(q=>[q.id,all.filter(q.test).length]));
for(const d of defs){const counts=new Map();for(const r of all)for(const value of tokens.get(r.issue).get(d.key))counts.set(value,(counts.get(value)||0)+1);totals.set(d.key,counts);universe.set(d.key,[...counts.keys()].sort((a,b)=>d.order?d.order.indexOf(a)-d.order.indexOf(b):(counts.get(b)-counts.get(a))||a.localeCompare(b,'zh-CN')));}
let restoreWarnings=[];
let resultRows=[],facetCounts=new Map(),filterFingerprint='',openFilter='',searchTimer,lastSearchAt=0,lastHash='',toastTimer;
const undoStack=[],detailCache=new Map(),pickerQueries=new Map(),pickerLimits=new Map();let currentDetail='',casePage=0,evidencePage=0,commentPage=0,commentFilter='all',restoring=false;
const selected=(key,value)=>(state.filters[key]||[]).includes(value);
const display=(key,value)=>value==='__empty__'?(defMap.get(key)?.empty||'未记录'):ageLabels[value]||value;
function snapshotState(){return JSON.parse(JSON.stringify(state));}
function setStatus(message){$('shareStatus').textContent=message;}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3000);}
function serialize(){const p=new URLSearchParams();p.set('v','3');if(state.view==='closure')p.set('view','closure');if(state.queue)p.set('queue',state.queue);if(state.query)p.set('q',state.query);Object.entries(state.filters).sort(([a],[b])=>a.localeCompare(b)).forEach(([k,vs])=>vs.forEach(v=>p.append('f.'+k,v)));if(state.sort!=='updated-desc')p.set('sort',state.sort);p.set('size',String(state.size));if(state.page!==1)p.set('page',String(state.page));return p.size>1?'#'+p.toString():'';}
function persist(mode='push'){const hash=serialize();if(location.hash!==hash){history[mode==='replace'?'replaceState':'pushState']({issueView:true},'',location.pathname+location.search+hash);}lastHash=hash;}
function restore(){
 clearTimeout(searchTimer);restoreWarnings=[];Object.assign(state,{view:'developer',queue:'',query:'',filters:{},sort:'updated-desc',page:1,size:location.hash?10:preferredSize()});
 const raw=location.hash.slice(1),p=new URLSearchParams(raw);
 if(raw.length>=20000){restoreWarnings.push('分享地址过长，未应用条件。请重新生成筛选链接。');state.query='__invalid_shared_view__';}
 else if(raw&& !['1','2','3'].includes(p.get('v'))){restoreWarnings.push('分享地址版本无法识别，未展开全部结果。请清除条件后重新筛选。');state.query='__invalid_shared_view__';}
 else if(raw){
  if(p.get('view')==='closure')state.view='closure';
  if(queues.some(q=>q.id===p.get('queue')))state.queue=p.get('queue');else if(p.get('queue')){restoreWarnings.push('队列已失效：'+p.get('queue'));state.query='__invalid_shared_view__';}
  if(p.has('q')&&!state.query)state.query=p.get('q');
  for(const d of defs){const requested=[...new Set(p.getAll('f.'+d.key))];if(requested.length)state.filters[d.key]=requested;for(const v of requested)if(!universe.get(d.key).includes(v))restoreWarnings.push(d.label+'条件在本快照中不存在：'+display(d.key,v));}
  for(const key of p.keys())if(key.startsWith('f.')&&!defMap.has(key.slice(2))){restoreWarnings.push('筛选字段已失效：'+key.slice(2));state.query='__invalid_shared_view__';}
  if([...$('sort').options].some(o=>o.value===p.get('sort')))state.sort=p.get('sort');
  if(p.has('size')&&[10,25,50,100].includes(Number(p.get('size'))))state.size=Number(p.get('size'));
  const page=Number(p.get('page'));if(Number.isSafeInteger(page)&&page>0)state.page=page;
 }
 $('search').value=state.query;$('sort').value=state.sort;$('pageSize').value=String(state.size);lastHash=location.hash;
}
function preferredSize(){try{const value=Number(localStorage.getItem('issue-workbench-size'));return [10,25,50,100].includes(value)?value:10;}catch{return 10;}}
function savePreference(key,value){try{localStorage.setItem('issue-workbench-'+key,String(value));}catch{}}
function rememberState(value){undoStack.push(value);if(undoStack.length>50)undoStack.shift();}

function mutate(fn,{resetPage=true,mode='push',remember=true}={}){clearTimeout(searchTimer);const before=snapshotState();state.query=$('search').value.trim();fn();if(resetPage)state.page=1;if(JSON.stringify(before)!==JSON.stringify(state)&&remember){rememberState(before);}render();persist(mode);}
function clearState(){restoreWarnings=[];state.queue='';state.query='';state.filters={};state.page=1;$('search').value='';}
function singleFilter(key,value){mutate(()=>{const was=state.view==='developer'&&!state.queue&&!state.query&&Object.keys(state.filters).length===1&&selected(key,value)&&(state.filters[key]||[]).length===1;clearState();state.view='developer';if(!was)state.filters[key]=[value];});goTo('worklist');}
function goTo(id){const el=$(id);if(!el)return;if(el.tagName==='DETAILS')el.open=true;el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});const heading=el.querySelector('h2')||el.querySelector('summary');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
function baseMatch(r){if(state.view==='closure'&&r.closure_candidate!=='1')return false;if(state.queue&&!queues.find(q=>q.id===state.queue)?.test(r))return false;if(!state.query)return true;return state.query.toLowerCase().split(/\s+/).filter(Boolean).every(term=>/^#\d+$/.test(term)?r.issue===term.slice(1):searchIndex.get(r.issue).includes(term));}
function compute(){const fingerprint=JSON.stringify([state.view,state.queue,state.query,state.filters]);if(fingerprint!==filterFingerprint){const base=all.filter(baseMatch),filters=Object.entries(state.filters);facetCounts=new Map(defs.map(d=>[d.key,new Map()]));resultRows=[];for(const r of base){const rt=tokens.get(r.issue);const failed=filters.filter(([key,vs])=>!vs.some(v=>rt.get(key)?.has(v))).map(([key])=>key);if(!failed.length)resultRows.push(r);if(failed.length<=1){for(const d of defs){if(failed.length&&failed[0]!==d.key)continue;const counts=facetCounts.get(d.key);for(const v of rt.get(d.key))counts.set(v,(counts.get(v)||0)+1);}}}filterFingerprint=fingerprint;}const rows=[...resultRows];const number=(r,k)=>Number(r[k])||0;rows.sort((a,b)=>{let diff=0;switch(state.sort){case 'closure-priority':diff=(closureRank[a.closure_status]??3)-(closureRank[b.closure_status]??3)||b.closure_latest_evidence.localeCompare(a.closure_latest_evidence);break;case 'age-desc':diff=number(b,'age_days')-number(a,'age_days');break;case 'age-asc':diff=number(a,'age_days')-number(b,'age_days');break;case 'issue-desc':diff=number(b,'issue')-number(a,'issue');break;case 'comments-desc':diff=number(b,'comment_count')-number(a,'comment_count');break;case 'activity-asc':case 'activity-desc':if(!a.last_human_comment_at&&b.last_human_comment_at)return 1;if(!b.last_human_comment_at&&a.last_human_comment_at)return -1;diff=state.sort==='activity-asc'?a.last_human_comment_at.localeCompare(b.last_human_comment_at):b.last_human_comment_at.localeCompare(a.last_human_comment_at);break;default:diff=b.updated_at_utc.localeCompare(a.updated_at_utc);}return diff||Number(b.issue)-Number(a.issue);});return rows;}
function initFilters(){for(const [index,d] of defs.entries()){const box=document.createElement('div');box.className='filter-control';box.dataset.filterControl=d.key;box.innerHTML=`<span class="filter-label" id="label-${d.key}">${esc(d.label)}</span><button class="button filter-trigger" id="filter-${d.key}" type="button" data-picker="${d.key}" aria-haspopup="dialog" aria-expanded="false" aria-controls="picker-${d.key}" aria-labelledby="label-${d.key} filter-${d.key}">全部</button><div class="filter-popover" id="picker-${d.key}" role="dialog" aria-labelledby="label-${d.key}" hidden><label class="sr-only" for="picker-search-${d.key}">搜索${esc(d.label)}选项</label><input class="filter-search" id="picker-search-${d.key}" data-picker-search="${d.key}" type="search" placeholder="输入关键字查找选项…" autocomplete="off"><div class="filter-options" id="picker-options-${d.key}" role="group" aria-label="${esc(d.label)}可选值"></div><div class="filter-footer"><span class="caption" id="picker-meta-${d.key}"></span><button type="button" class="button" data-picker-clear="${d.key}">清除此项</button><button type="button" class="button" data-picker-close="${d.key}">完成</button></div></div>`;$(index<4?'filters':'advancedFilters').append(box);}}
function closePicker(focus=false){if(!openFilter)return;const key=openFilter;$('picker-'+key).hidden=true;$('filter-'+key).setAttribute('aria-expanded','false');openFilter='';if(focus)$('filter-'+key).focus();}
function showPicker(key){if(openFilter===key){closePicker(true);return;}closePicker();openFilter=key;$('picker-'+key).hidden=false;$('filter-'+key).setAttribute('aria-expanded','true');renderPicker(key);$('picker-search-'+key).focus();}
function renderPicker(key){const query=(pickerQueries.get(key)||'').toLowerCase(),counts=facetCounts.get(key)||totals.get(key),d=defMap.get(key);const matches=universe.get(key).filter(v=>display(key,v).toLowerCase().includes(query));const limit=pickerLimits.get(key)||60;const sorted=[...matches].sort((a,b)=>Number(selected(key,b))-Number(selected(key,a))||0);const shown=sorted.slice(0,limit);$('picker-options-'+key).innerHTML=shown.map(v=>`<label class="filter-option"><input type="checkbox" data-option-key="${key}" data-option-value="${esc(v)}" ${selected(key,v)?'checked':''} ${!counts.get(v)&&!selected(key,v)?'disabled':''}><span>${esc(display(key,v))}</span><span class="count">${counts.get(v)||0}</span></label>`).join('')+(matches.length>limit?`<button type="button" class="button" data-picker-more="${key}">再显示 ${Math.min(60,matches.length-limit)} 项</button>`:'')||'<p class="filter-empty">没有匹配选项</p>';$('picker-meta-'+key).textContent=`${matches.length} 个匹配值 · 已选 ${(state.filters[key]||[]).length} 项`;}
function renderFilterLabels(){for(const d of defs){const vs=state.filters[d.key]||[],el=$('filter-'+d.key);el.textContent=vs.length?vs.length===1?display(d.key,vs[0]):`已选 ${vs.length} 项`:'全部';el.title=vs.map(v=>display(d.key,v)).join('、');}if(openFilter){const active=document.activeElement,key=openFilter,value=active?.dataset?.optionValue;renderPicker(key);if(value)document.querySelector(`[data-option-key="${key}"][data-option-value="${CSS.escape(value)}"]`)?.focus({preventScroll:true});}}
function renderChips(){const chips=[];if(state.queue)chips.push(`<button class="chip" data-remove-queue type="button">队列：${esc(queues.find(q=>q.id===state.queue).title)} ×</button>`);if(state.query)chips.push(`<button class="chip" data-remove-search type="button">搜索：${esc(state.query)} ×</button>`);for(const [key,vs] of Object.entries(state.filters))for(const v of vs)chips.push(`<button class="chip" data-remove-key="${key}" data-remove-value="${esc(v)}" type="button">${esc(defMap.get(key).label)}：${esc(display(key,v))} ×</button>`);$('chips').innerHTML=chips.join('');}
function renderFacts(){const items=[['未关闭 issue',all.length],['待审查关闭',all.filter(r=>r.closure_candidate==='1').length],['带 regression 标签',all.filter(r=>r.regression_label==='1').length],['带 skipped 标签',all.filter(r=>r.skipped_label==='1').length],['关闭引用 PR 进行中',all.filter(r=>r.repair_pr_status==='明确关闭引用 PR 进行中').length],['关闭引用 PR 的 CI 失败',all.filter(r=>r.pr_ci_failed==='1').length],['关闭引用已合并仍 Open',all.filter(r=>r.repair_pr_status==='明确关闭引用 PR 已合并').length]];$('facts').innerHTML=items.map(([label,count])=>`<button type="button" class="fact" ${label==='待审查关闭'?'data-view="closure"':label==='带 regression 标签'?'data-queue="regression"':label==='带 skipped 标签'?'data-queue="skipped"':label==='关闭引用 PR 的 CI 失败'?'data-queue="ci"':label==='关闭引用已合并仍 Open'?'data-queue="merged"':label==='关闭引用 PR 进行中'?'data-open-fix':'data-view="developer"'}><strong>${count}</strong><span>${esc(label)} · 条</span></button>`).join('');}
function initQueues(){const groups=[...new Set(queues.map(q=>q.group))];$('queues').innerHTML=groups.map(g=>`<div class="queue-group"><h3>${g}</h3>${queues.filter(q=>q.group===g).map(q=>`<button class="queue" data-queue="${q.id}" type="button" aria-pressed="false"><span><span class="queue-label">${q.title}</span><small>${q.hint}</small></span><span class="queue-count">${queueCounts.get(q.id)}</span></button>`).join('')}</div>`).join('');}
function updateQueues(){for(const el of document.querySelectorAll('[data-queue]'))el.setAttribute('aria-pressed',String(state.queue===el.dataset.queue));$('queueNote').textContent=state.queue?'当前队列：'+queues.find(q=>q.id===state.queue).title+'。数量以完整快照按 issue 去重，需核对公开证据。':'按开发工作选择队列，再用多选筛选器缩小范围。未设置负责人不推断为实际阻塞。';}
function materialBadges(r){return `<span class="material ${r.test_paths?'present':''}">测试入口：${r.test_paths?'有线索':'未提取'}</span><span class="material ${r.repro_code_present==='1'?'present':''}">代码：${r.repro_code_present==='1'?'有线索':'未提取'}</span><span class="material ${r.reported_pytorch_version?'present':''}">报告版本：${r.reported_pytorch_version?'有':'未提取'}</span>`;}
function repairCell(r){const open=linkedFor(r).filter(p=>p.explicit_fix_reference&&p.state==='OPEN'),failed=open.filter(p=>['FAILURE','ERROR'].includes(p.checks)),conflicts=open.filter(p=>p.mergeable==='CONFLICTING'),drafts=open.filter(p=>p.is_draft);return `<span class="pill">${esc(r.repair_pr_status)}</span>${open.length?`<div class="minor">${open.length} 个进行中${drafts.length?' · 草稿 '+drafts.length:''}</div>`:''}${failed.length?`<span class="pill amber">CI 失败 ${failed.length}</span>`:''}${conflicts.length?`<span class="pill amber">合并冲突 ${conflicts.length}</span>`:''}${open.slice(0,2).map(p=>`<div class="minor">${esc(p.repository)}#${p.number} · ${esc(p.stage)}</div>`).join('')}${open.length>2?`<div class="minor">另 ${open.length-2} 个，见详情</div>`:''}<div class="minor">关闭引用 ${r.explicit_fix_pr_count} · 普通引用 ${r.cross_reference_pr_count}</div>`;}
function closurePill(status){return `<span class="pill ${status==='优先审查关闭'?'teal':status==='存在未完成事项'?'amber':''}">${esc(status)}</span>`;}
function caseSummary(r){const total=n(r,'closure_case_total');if(!total)return '<span class="minor">覆盖未知 · 未识别完整清单</span>';return `<strong>${n(r,'closure_case_disposed')} / ${total}</strong> 有处理结论${r.closure_inventory_complete==='1'?'':`<div class="minor">覆盖未知${r.closure_declared_total?' · 原文声明 '+esc(r.closure_declared_total)+' 项':' · 清单不完整'}</div>`}<div class="minor">${Object.entries(D.case_statuses).filter(([k])=>n(r,'closure_case_'+k)).map(([k,label])=>esc(label)+' '+n(r,'closure_case_'+k)).join(' · ')}</div>`;}
function renderClosureHub(){const candidates=all.filter(r=>r.closure_candidate==='1');$('closureStats').innerHTML=['优先审查关闭','需要补充确认','存在未完成事项'].map(status=>`<button type="button" class="closure-stat" data-closure-status="${status}"><strong>${candidates.filter(r=>r.closure_status===status).length}</strong><span>${status}</span></button>`).join('');const reasons=[...new Set(candidates.flatMap(r=>r.closure_reasons.split('；')))];$('closureReasons').innerHTML=reasons.map(reason=>`<button type="button" class="chip" data-closure-reason="${esc(reason)}">${esc(reason)} · ${candidates.filter(r=>r.closure_reasons.split('；').includes(reason)).length}</button>`).join('')||'<p class="caption">当前未提取到关闭候选依据。</p>';}
function enterClosure(key,value){mutate(()=>{clearState();state.view='closure';state.sort='closure-priority';$('sort').value=state.sort;if(key)state.filters[key]=[value];});goTo('worklist');}

function renderTable(rows){
 const review=state.view==='closure',total=rows.length,pages=Math.max(1,Math.ceil(total/state.size));state.page=Math.min(state.page,pages);const start=(state.page-1)*state.size,shown=rows.slice(start,start+state.size);
 $('worklistTitle').textContent=review?'待审查关闭 · 工作清单':'Issue 工作清单';
 $('resultCount').textContent=`${total} 条结果 / ${review?all.filter(r=>r.closure_candidate==='1').length:all.length} 条${review?'关闭审查候选':'未关闭 issue'}`;
 $('worklistHint').textContent=review?'规则筛出的审查线索；skip、删除线与 PR 合并均需核对。可导出当前清单，详情查看逐项证据。':'同维度多选取并集，不同维度取交集。搜索覆盖清单字段，详情中的全部评论不参与搜索。';
 const headers=review?['Issue / 标题','候选原因 / 状态','用例处理情况','未完成事项 / 待确认','最近证据','操作']:['Issue / 标题','技术范围','负责人 / 目标版本','关闭引用 PR','最近更新','操作'];
 $('worklistHead').innerHTML='<tr>'+headers.map(label=>`<th scope="col">${label==='操作'?'<span class="sr-only">操作</span>':label}</th>`).join('')+'</tr>';
 document.querySelector('.issue-table').classList.toggle('closure-table',review);
 $('rows').innerHTML=shown.map(r=>`<tr><td><button type="button" class="issue-button" data-issue="${r.issue}"><span class="issue-number">#${r.issue}</span>${!review&&r.regression_label==='1'?'<span class="pill amber">regression</span>':''}<span class="issue-title">${esc(r.title)}</span></button>${review?`<div class="minor">${esc(r.assignees||'未设置 assignee')}</div>`:''}</td>${review?`<td>${closurePill(r.closure_status)}<div class="minor">${esc(r.closure_reasons)}</div></td><td>${caseSummary(r)}</td><td>${r.closure_blockers?`<p class="closure-blocker">${esc(r.closure_blockers)}</p>`:''}<p class="minor">${esc(r.closure_checks||'需维护者最终核对覆盖范围与关闭结论')}</p></td><td><span class="date">${r.closure_latest_evidence||'未提取'}</span><div class="minor">更新 ${r.updated_at}</div></td>`:`<td>${esc(r.surface_scope)}<div class="minor">${esc(r.public_record_status)}</div></td><td>${esc(r.assignees||'未设置')}<div class="minor">${esc(r.milestone||'无 milestone')}</div></td><td>${repairCell(r)}</td><td><span class="date">${r.updated_at}</span><div class="minor">创建 ${r.age_days} 天</div></td>`}<td><button type="button" class="row-copy" data-copy-issue="${r.issue}" aria-label="复制 issue ${r.issue} 编号" title="复制编号">⧉</button></td></tr>`).join('')||'<tr><td class="empty" colspan="6">没有符合条件的 issue。可以移除条件或清除筛选。</td></tr>';
 $('pageInfo').textContent=total?`${start+1}–${Math.min(start+state.size,total)} 条 · ${state.page}/${pages} 页`:'0 条 · 1/1 页';$('prev').disabled=state.page<=1;$('next').disabled=state.page>=pages;$('export').disabled=!total;
 for(const el of document.querySelectorAll('.view-switch [data-view]'))el.setAttribute('aria-pressed',String(el.dataset.view===state.view));
}

function bars(id,key,rows,global=true){const counts=global?totals.get(key):new Map();if(!global)for(const r of rows)for(const value of tokens.get(r.issue).get(key))counts.set(value,(counts.get(value)||0)+1);const d=defMap.get(key),items=[...counts.entries()].sort((a,b)=>d?.order?d.order.indexOf(a[0])-d.order.indexOf(b[0]):b[1]-a[1]||a[0].localeCompare(b[0],'zh-CN'));$(id).innerHTML=items.map(([v,count])=>{const pct=count/(rows.length||1)*100;return `<button type="button" class="bar ${v==='影响未知'||v==='未知'?'unknown':''}" data-chart-key="${key}" data-chart-value="${esc(v)}" data-chart-global="${global}" data-count="${count}" aria-pressed="false" aria-label="${esc(display(key,v))}，${count} 条，${pct.toFixed(1)}%"><span class="bar-label">${esc(display(key,v))}</span><span class="track"><span class="fill" style="width:${pct}%"></span></span><span class="bar-count">${count} · ${pct.toFixed(1)}%</span></button>`;}).join('')||'<p class="caption">当前没有记录</p>';}
function renderOverview(){const top=[...totals.get('surface_scope')].filter(([v])=>v!=='未知').sort((a,b)=>b[1]-a[1])[0],aged=all.filter(r=>n(r,'age_days')>180).length;$('overviewSummary').innerHTML=`<strong>${esc(top?.[0]||'未知')}</strong> 数量最多，<strong>${top?.[1]||0} 条</strong>；创建超过 180 天 <strong>${aged} 条</strong>。技术范围和影响均是公开线索；未知保留为待核查。`;$('overviewDenominator').textContent=`固定分母：完整快照 ${all.length} 条。点击分类后，下方清单会进入对应记录。`;for(const [id,key] of [['overviewScope','surface_scope'],['overviewAge','age_bucket'],['overviewNature','public_record_status'],['overviewProgress','current_progress'],['overviewImpact','impact_types']]){if(!totals.has(key)){const counts=new Map();for(const r of all)counts.set(r[key],(counts.get(r[key])||0)+1);totals.set(key,counts);}bars(id,key,all);}}
let extraRendered=false;
function renderExtra(){if(extraRendered)return;extraRendered=true;for(const [id,key] of [['overviewBlocker','primary_blocker'],['overviewOwner','owner_status'],['overviewPR','repair_pr_status'],['overviewMilestone','milestone'],['overviewOS','os_in_title'],['overviewDiscovery','discovery_channels'],['overviewMaterials','repro_materials'],['overviewRelations','pr_relation'],['overviewHardware','hardware_in_title']])bars(id,key,all);updateChartSelection();}
const matrixScopes=[...totals.get('surface_scope')].sort((a,b)=>b[1]-a[1]).map(([scope])=>scope);
const matrixData=matrixScopes.map(scope=>({scope,rows:all.filter(r=>r.surface_scope===scope),counts:new Map(D.impact_types.map(type=>[type,all.filter(r=>r.surface_scope===scope&&tokens.get(r.issue).get('impact_types').has(type)).length]))}));
let matrixRendered=false;
function renderMatrix(){matrixRendered=true;const mode=$('matrixMode').value;const max=Math.max(1,...matrixData.flatMap(x=>[...x.counts.entries()].filter(([type])=>type!=='影响未知').map(([,count])=>count)));const short={'崩溃/稳定性':'崩溃 / 稳定性','算子/API 不支持':'缺少支持','测试/CI 基础设施故障':'测试 / CI 故障','测试预期需核对':'测试预期','功能/改进':'功能 / 改进'};$('matrixHead').innerHTML='<tr><th scope="col">技术范围</th><th scope="col">全部 issue</th>'+D.impact_types.map(type=>`<th scope="col">${esc(short[type]||type)}</th>`).join('')+'</tr>';$('matrixRows').innerHTML=matrixData.map(x=>`<tr><th scope="row">${esc(x.scope)}</th><td><button class="matrix-count" type="button" data-matrix-scope="${esc(x.scope)}" data-count="${x.rows.length}">${x.rows.length}</button></td>${D.impact_types.map(type=>{const count=x.counts.get(type),pct=count/x.rows.length*100,heat=mode==='percent'?pct:count/max*100;return `<td><button type="button" class="matrix-count ${type==='影响未知'?'unknown':''}" data-matrix-scope="${esc(x.scope)}" data-matrix-impact="${esc(type)}" data-count="${count}" data-pct="${pct.toFixed(1)}" style="--heat:${count?8+heat*.3:0}%" ${count?'':'disabled'} aria-pressed="false" aria-label="${esc(x.scope)}，${esc(type)}，${count} 条，占模块 ${pct.toFixed(1)}%">${mode==='percent'?(count?pct.toFixed(1)+'%':'—'):count||'—'}${mode==='percent'&&count?`<small>${count} 条</small>`:''}</button></td>`}).join('')}</tr>`).join('');$('matrixTotal').textContent=`全量 ${all.length} 条 · ${mode==='percent'?'百分比以行内 issue 总数为分母':'单元格按 issue 去重'}`;updateMatrixSelection();}
function updateMatrixSelection(){for(const el of document.querySelectorAll('[data-matrix-impact]'))el.setAttribute('aria-pressed',String(!state.queue&&!state.query&&selected('surface_scope',el.dataset.matrixScope)&&selected('impact_types',el.dataset.matrixImpact)));}
function updateChartSelection(){for(const el of document.querySelectorAll('[data-chart-key]'))el.setAttribute('aria-pressed',String(selected(el.dataset.chartKey,el.dataset.chartValue)));}
function renderFilteredCharts(rows){if(!$('filteredCharts').open)return;$('chartDenominator').textContent=`当前子集 ${rows.length} 条；比例使用当前子集为分母。`;for(const [id,key] of [['progressChart','current_progress'],['blockerChart','primary_blocker'],['impactChart','impact_types']]){if(!defMap.has(key)){for(const r of all)tokens.get(r.issue).set(key,new Set([r[key]||'__empty__']));}bars(id,key,rows,false);}updateChartSelection();}
let scopeRendered=false;
function renderScopes(){scopeRendered=true;const measures=[['all',r=>true],['old',r=>n(r,'age_days')>180],['unassigned',r=>!r.assignees],['openpr',r=>r.repair_pr_status==='明确关闭引用 PR 进行中']];$('scopeRows').innerHTML=matrixData.map(x=>`<tr><th scope="row">${esc(x.scope)}</th>${measures.map(([id,test])=>{const count=x.rows.filter(test).length;return `<td><button class="metric-button" type="button" data-scope="${esc(x.scope)}" data-measure="${id}" data-count="${count}" ${count?'':'disabled'}>${count}</button></td>`}).join('')}</tr>`).join('')+`<tr><th scope="row">合计</th>${measures.map(([,test])=>`<td>${all.filter(test).length}</td>`).join('')}</tr>`;}
function renderQuality(){const percent=count=>(count/all.length*100).toFixed(1)+'%';$('qualityCards').innerHTML=qualityDefs.map(q=>{const count=all.filter(q.test).length;return `<button type="button" class="quality-card" data-quality="${q.id}" ${count?'':'disabled'} aria-label="${q.title}，${count} 条，${percent(count)}"><strong>${count} <small>/ ${percent(count)}</small></strong><span>${q.title}</span><small>${q.hint}</small></button>`}).join('');$('collectionInfo').textContent=`已核对 ${all.length} 条 open issue 集合、${D.collection.linked_pr_count} 个去重关联 PR、${D.collection.comment_count} 条评论（${D.collection.markdown_comment_count||0} 条保留 Markdown）、${D.collection.workflow_run_count||0} 条运行记录（${D.collection.workflow_run_available||0} 条可访问）。集合核对：${D.collection.open_set_verified_at.replace('T',' ').slice(0,19)} UTC。详情和评论仅在展开时解析。`;}
function getDetail(id){if(!detailCache.has(id)){const block=$('detail-'+id);if(!block)return null;detailCache.set(id,JSON.parse(block.textContent));}return detailCache.get(id);}
function copyHeading(label,kind,extra=''){return `<div class="copy-heading"><h3>${label}</h3><button type="button" class="button" data-copy-detail="${kind}" ${extra}>复制</button></div>`;}
function prCards(r){const allPrs=linkedFor(r),fix=allPrs.filter(p=>p.explicit_fix_reference),refs=allPrs.filter(p=>!p.explicit_fix_reference);const cards=items=>items.map(p=>`<article class="pr-card"><div class="pr-title"><h3>${esc(p.repository)}#${p.number} · ${esc(p.title)}</h3><span class="pill ${['FAILURE','ERROR'].includes(p.checks)?'amber':''}">${esc(p.stage)}</span></div><div class="pr-meta"><span>状态 ${p.state}${p.is_draft?' · Draft':''}</span><span>检查 ${esc(p.checks)}</span><span>审查 ${esc(p.review)}</span><span>可合并 ${esc(p.mergeable)}</span><span>合并状态 ${esc(p.merge_state)}</span><span>更新 ${p.updated_at.slice(0,10)}</span><span class="code">${esc(p.head)} → ${esc(p.base)}</span><span>变更文件 ${p.changed_files}</span></div>${p.failed_checks.length?`<p class="caption">最新提交未通过的检查</p><pre class="evidence code">${esc(p.failed_checks.join('\n'))}</pre>`:''}${!p.check_details_complete?'<p class="caption">检查名称最多展示 100 项，总状态完整。</p>':''}<p class="minor code">提交 ${esc(p.commit||'未提供')}</p></article>`).join('');return `<section data-pr-group="fix"><h3>明确关闭引用 · ${fix.length} 个 PR</h3><p class="caption">关闭引用不保证已修复，仍需核对目标分支、修复范围和验证结果。</p>${cards(fix)||'<p class="caption">未发现明确关闭引用。</p>'}</section><details class="disclosure" data-pr-group="reference"><summary>普通交叉引用 · ${refs.length} 个 PR</summary><p class="caption">未提供明确关闭引用，不排除修复关系。其检查不计入关闭引用 PR 队列。</p><div id="ordinaryPRs" data-lazy-prs="true"></div></details>`;}
function showIssue(id){const r=rowById.get(id),detail=getDetail(id);if(!r||!detail)return;currentDetail=id;casePage=0;evidencePage=0;commentPage=0;commentFilter='all';$('dialogNumber').textContent=`ISSUE #${id} · 快照 ${D.snapshot_local} 北京时间`;$('dialogTitle').textContent=r.title;const fields=[['技术范围',r.surface_scope],['记录性质',r.public_record_status],['问题表现',r.impact_types],['GitHub assignee',r.assignees||'未设置'],['目标 Milestone',r.milestone||'未设置'],['负责人状态',r.owner_status],['公开阻塞线索',r.primary_blocker],['阻塞依据',r.blocker_evidence],['报告中的环境',r.environment],['报告中的 PyTorch 版本',r.reported_pytorch_version||'未提取到'],['对比基线版本',r.baseline_pytorch_version||'未提取到'],['其他版本线索',r.other_version_clues||'未提取到'],['最近已核查验证版本',r.latest_verified_version],['验证线索状态',r.verification_status],['创建 / 最近更新',r.created_at+' / '+r.updated_at],['最近人工评论',r.last_human_comment_at||'未记录'],['范围分类依据',r.scope_evidence],['影响分类依据',r.impact_evidence],['核查状态',r.classification_review],['发现渠道',r.discovery_channels]];const review=detail.review;const verification=review?.set?.verification;const blocks=detail.repro_code_blocks||[];const candidates=detail.verification_candidates||[];$('dialogContent').innerHTML=`<div class="detail-actions"><button type="button" class="button" data-copy-issue="${id}">复制 #${id}</button><button type="button" class="button" data-copy-detail="title">复制标题</button></div>${closureDetail(r,detail)}<div class="action-note"><strong>建议核查：</strong>${esc(r.engineering_action)}<p class="caption">规则生成的核查方向；跟踪事项、材料和修复状态以公开证据为准。</p></div><dl class="detail-grid">${fields.map(([key,value])=>`<div><dt>${key}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><div class="material-list">${materialBadges(r)}</div>${copyHeading('测试入口','test')}<pre class="evidence code">${esc(r.test_paths||'未提取到明确测试入口')}</pre>${copyHeading('显式源码路径','source')}<pre class="evidence code">${esc(r.source_paths||'未提取到明确源码路径，不推测根因文件')}</pre><section class="detail-section"><h3>验证证据</h3>${verification?`<p class="pill teal">已人工核查</p><p class="evidence">${esc(verification.date+' · '+verification.version+' · '+verification.hardware+' · '+verification.result+'\n'+verification.evidence)}</p>`:'<p class="caption">最近验证版本未确认。下面仅展示人工评论中的验证线索，不把计划验证、历史报告版本或关键词自动视为当前复现结果。</p>'}${candidates.map(c=>`<div class="candidate"><p class="caption">${esc(c.date+' · '+c.author)} · 待核查</p><p>${esc(c.excerpt)}</p></div>`).join('')||'<p class="caption">未提取到明确验证评论线索。</p>'}</section>${review?`<section class="detail-section"><h3>人工核查记录</h3><p class="evidence">${esc(review.reviewer+' · '+review.reviewed_at+'\n'+review.reason+'\n依据：'+review.evidence)}</p></section>`:''}<details class="disclosure" id="codeDetails"><summary>复现代码与命令材料 · ${blocks.length} 个完整原文代码块</summary><p class="caption">复制保留原始代码块的缩进与顺序，仅移除地址。材料未在页面执行。若没有完整代码块，代码行摘录不可作为完整脚本。</p>${blocks.map((code,index)=>`${copyHeading('原文代码块 '+(index+1),'code',`data-code-index="${index}"`)}<pre class="evidence code">${esc(code)}</pre>`).join('')}${!blocks.length&&detail.repro_code_excerpt?`${copyHeading('正文代码行线索（不完整）','excerpt')}<pre class="evidence code">${esc(detail.repro_code_excerpt)}</pre>`:''}${detail.repro_commands?`${copyHeading('正文复现命令线索','commands')}<pre class="evidence code">${esc(detail.repro_commands)}</pre>`:''}${!blocks.length&&!detail.repro_code_excerpt&&!detail.repro_commands?'<p class="caption">未提取到代码或命令材料。</p>':''}</details><section class="detail-section"><h3>PR 引用证据</h3>${prCards(r)}</section><details class="disclosure" id="bodyDetails"><summary>完整 Issue 正文 · 按需展示</summary><div id="bodyContent"></div></details><details class="disclosure" id="commentDetails"><summary>全部 ${detail.comments.length} 条评论 · 按需展示，每批 20 条</summary><div class="detail-actions"><label class="inline-field">评论 <select id="commentKind"><option value="all">全部（含 Bot）</option><option value="human">仅人工评论</option></select></label></div><div id="commentContent"></div><button id="moreComments" type="button" class="button">加载更多评论</button></details><details class="disclosure"><summary>原始标签</summary><p class="evidence">${esc(r.labels_raw||'无标签')}</p></details>`;for(const section of [$('bodyDetails'),$('commentDetails'),document.querySelector('[data-pr-group="reference"]')])section.addEventListener('toggle',lazyDetail);$('commentKind').addEventListener('change',()=>{commentFilter=$('commentKind').value;commentPage=0;renderComments();});$('moreComments').addEventListener('click',()=>{commentPage++;renderComments();});$('closureEvidence')?.addEventListener('toggle',()=>{if($('closureEvidence').open&&!$('closureEvidenceRows').hasChildNodes())renderClosureEvidence();});$('moreEvidence')?.addEventListener('click',()=>{evidencePage++;renderClosureEvidence();});$('caseDetails')?.addEventListener('toggle',()=>{if($('caseDetails').open&&!$('caseRows').hasChildNodes())renderCases();});$('moreCases')?.addEventListener('click',()=>{casePage++;renderCases();});$('issueDialog').showModal();}
function lazyDetail(event){if(!event.target.open)return;const detail=getDetail(currentDetail);if(event.target.id==='bodyDetails'&&!$('bodyContent').hasChildNodes())$('bodyContent').innerHTML=`${copyHeading('完整正文（Markdown 或纯文本）','body')}<pre class="detail-body code">${esc(detail.body_markdown||detail.body_text||'无正文')}</pre>`;if(event.target.id==='commentDetails'&&!$('commentContent').hasChildNodes())renderComments();if(event.target.dataset.prGroup==='reference'&&!$('ordinaryPRs').hasChildNodes()){const r=rowById.get(currentDetail),refs=linkedFor(r).filter(p=>!p.explicit_fix_reference);$('ordinaryPRs').innerHTML=refs.map(p=>`<article class="pr-card"><h3>${esc(p.repository)}#${p.number} · ${esc(p.title)}</h3><p class="caption">${esc(p.stage)} · 检查 ${esc(p.checks)} · 审查 ${esc(p.review)}</p>${p.failed_checks.length?`<pre class="evidence code">${esc(p.failed_checks.join('\n'))}</pre>`:''}</article>`).join('')||'<p class="caption">没有普通交叉引用。</p>';}}
function renderComments(){const detail=getDetail(currentDetail);const comments=[...detail.comments].reverse().filter(c=>commentFilter==='all'||!c.is_bot);const limit=(commentPage+1)*20;$('commentContent').innerHTML=comments.slice(0,limit).map(c=>`<article class="comment"><strong>${esc(c.author)}</strong>${c.is_bot?'<span class="pill">Bot / 非人工评论</span>':''}<span class="comment-meta"> · ${c.created_at.slice(0,19).replace('T',' ')} UTC</span><p>${esc(c.text)}</p></article>`).join('')||'<p class="caption">没有匹配的评论。</p>';$('moreComments').hidden=limit>=comments.length;$('moreComments').textContent=`再加载 ${Math.min(20,comments.length-limit)} 条（已显示 ${Math.min(limit,comments.length)} / ${comments.length}）`;}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制');return true;}catch{$('copyFallback').value=text;if(!$('copyDialog').open)$('copyDialog').showModal();$('copyFallback').focus();$('copyFallback').select();return false;}}
function runMetadata(runs){return (runs||[]).map(value=>{const run=typeof value==='string'?(D.workflow_runs?.[value]||{reference:value,available:false}):value;return `<div class="run-record"><span class="code">${esc(run.reference||((run.repository||'')+'@run:'+run.run_id))}</span>${run.available?`<p>${esc(run.name+' · '+run.path)}</p><p class="code">${esc('分支 '+run.branch+' · commit '+run.commit)}</p><p>整体运行结论 ${esc(run.conclusion||'未提供')} · ${esc(run.created_at||'')}（整体结论不代替单个用例结果）</p>`:`<p>${esc(run.reason||'运行配置未核对')}</p>`}</div>`;}).join('');}
function evidenceMeta(e){const config=e.configuration||{},platform=[...(config.hardware||[]),...(config.os||[]),...(config.versions||[])].join(' · ');return `<p class="caption">${esc((e.timestamp||e.date)+' · '+e.author+' · '+e.source+(e.comment_id?' · 评论记录 '+e.comment_id:''))}</p>${platform?`<p class="minor">记录中的配置线索：${esc(platform)}</p>`:''}${runMetadata(config.runs)}${e.references.length?`<p class="minor code">${esc(e.references.join(' · '))}</p>`:''}`;}
function closureDetail(r,detail){const c=detail.closure_review;if(!c)return '';return `<section class="closure-detail"><div class="section-heading"><h3>关闭审查依据</h3>${closurePill(c.status)}</div><p>${esc(c.reasons.join('；')||'当前未提取到关闭候选依据')}</p><div class="material-list">${caseSummary(r)}</div><p class="caption">验证配置核对：${esc(c.configuration?.status||'覆盖未知')}</p>${c.configuration?.original_runs?.length?`<details class="disclosure"><summary>原报告运行配置 · ${c.configuration.original_runs.length} 条</summary>${runMetadata(c.configuration.original_runs)}</details>`:''}${c.blockers.length?`<div class="review-blockers"><strong>未完成事项</strong><ul>${c.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<p class="caption">关闭前需确认：${esc(c.checks.join('；')||'核对全部任务、目标版本与原报告范围，由维护者给出最终结论。')}</p><details class="disclosure" id="closureEvidence"><summary>判断证据 · ${c.evidence.length} 条 · 按需展示</summary><div id="closureEvidenceRows"></div><button type="button" class="button" id="moreEvidence">加载更多证据</button></details>${c.related_records?.length?`<details class="disclosure"><summary>相关问题引用 · ${c.related_records.length} 条 · 不作为关闭依据</summary>${c.related_records.map(e=>`<article class="candidate"><p>${esc(e.excerpt)}</p>${evidenceMeta(e)}</article>`).join('')}</details>`:''}<details class="disclosure" id="caseDetails"><summary>逐项用例 · ${c.total} 项 · ${c.inventory_complete?'已解析声明清单':'覆盖未知'}</summary><p class="caption">每项状态来自公开记录，不表示页面重新执行测试。删除线未直接视为通过；平台、版本与最新失败反馈需结合原文核对。</p><div id="caseRows"></div><button type="button" class="button" id="moreCases">加载更多用例</button></details></section>`;}
function renderClosureEvidence(){const es=getDetail(currentDetail).closure_review.evidence,limit=(evidencePage+1)*20;$('closureEvidenceRows').innerHTML=es.slice(0,limit).map(e=>`<article class="candidate"><p class="caption">${esc(e.kind)}</p><p>${esc(e.excerpt)}</p>${evidenceMeta(e)}</article>`).join('')||'<p class="caption">未提取到可用于关闭审查的证据。</p>';$('moreEvidence').hidden=limit>=es.length;$('moreEvidence').textContent=`再加载 ${Math.min(20,es.length-limit)} 条（已显示 ${Math.min(limit,es.length)} / ${es.length}）`;}
function renderCases(){const c=getDetail(currentDetail).closure_review,limit=(casePage+1)*30;$('caseRows').innerHTML=c.cases.slice(0,limit).map(x=>`<article class="case-record"><strong class="code">${esc(x.name)}</strong><span class="pill ${x.status==='failed'?'amber':x.status==='passed'?'teal':''}">${esc(D.case_statuses[x.status])}</span><p class="caption">清单来源：${esc(x.inventory_source||'原报告')}</p>${x.aliases?.length?`<p class="minor code">评论中明确迁移后的标识：${esc(x.aliases.join(' · '))}</p>`:''}${x.configuration_status?`<p class="caption">配置：${esc(x.configuration_status)}${x.configuration_notes?.length?' · '+esc(x.configuration_notes.join('；')):''}</p>`:''}${x.evidence.map(e=>`<p class="minor">${esc(e.excerpt)}</p>${evidenceMeta(e)}`).join('')||'<p class="caption">未提取到该用例的处理证据。</p>'}</article>`).join('')||'<p class="caption">未提取到可完整核对的用例清单。</p>';$('moreCases').hidden=limit>=c.total;$('moreCases').textContent=`再加载 ${Math.min(30,c.total-limit)} 项（已显示 ${Math.min(limit,c.total)} / ${c.total}）`;}

function csvCell(value){let text=String(value??'');if(/^[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';}
function flushSearch(){if($('search').value.trim()!==state.query)mutate(()=>{}, {mode:'replace'});}
function exportCSV(){flushSearch();const rows=compute();const csv='\uFEFF'+[D.fields,...rows.map(r=>D.fields.map(k=>r[k]))].map(row=>row.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`torch-xpu-ops-filtered-${D.snapshot}-${rows.length}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){restoreWarnings=[];for(const [key,vs] of Object.entries(state.filters))for(const value of vs)if(!universe.get(key)?.includes(value))restoreWarnings.push((defMap.get(key)?.label||key)+'条件在本快照中不存在：'+display(key,value));if(state.query==='__invalid_shared_view__')restoreWarnings.unshift('分享条件无法识别，请清除条件后重新筛选');const rows=compute();renderFilterLabels();renderChips();renderTable(rows);updateQueues();updateChartSelection();if(matrixRendered)updateMatrixSelection();renderFilteredCharts(rows);$('undo').disabled=!undoStack.length;$('restoreNotice').hidden=!restoreWarnings.length;$('restoreNotice').textContent=restoreWarnings.length?'分享条件需核对：'+restoreWarnings.join('；')+'。已保留原条件，失效值不会自动扩大结果。':'';setStatus('');}
function init(){initFilters();renderFacts();initQueues();renderClosureHub();renderOverview();renderQuality();restore();render();persist('replace');if(defs.slice(4).some(d=>state.filters[d.key]))document.querySelector('.advanced').open=true;try{const saved=JSON.parse(localStorage.getItem('issue-workbench-panels')||'{}');for(const id of ['overview','impactMatrix','extraOverview','scopePanel'])if(typeof saved[id]==='boolean')$(id).open=saved[id];}catch{}if(state.view==='closure'||state.queue||state.query||Object.keys(state.filters).length)requestAnimationFrame(()=>goTo('worklist'));}
document.addEventListener('click',event=>{
 const target=event.target;
 if(target.closest('[data-open-fix]')){singleFilter('repair_pr_status','明确关闭引用 PR 进行中');return;}
 const view=target.closest('[data-view]');if(view){closePicker();if(view.dataset.view==='closure')enterClosure();else{mutate(()=>{clearState();state.view='developer';state.sort='updated-desc';$('sort').value=state.sort;});goTo('worklist');}return;}
 const closureStatus=target.closest('[data-closure-status]');if(closureStatus){enterClosure('closure_status',closureStatus.dataset.closureStatus);return;}
 const closureReason=target.closest('[data-closure-reason]');if(closureReason){enterClosure('closure_reasons',closureReason.dataset.closureReason);return;}
 const nav=target.closest('[data-nav]');if(nav){closePicker();goTo(nav.dataset.nav);return;}
 const picker=target.closest('[data-picker]');if(picker){showPicker(picker.dataset.picker);return;}
 const done=target.closest('[data-picker-close]');if(done){closePicker(true);return;}
 const clear=target.closest('[data-picker-clear]');if(clear){mutate(()=>delete state.filters[clear.dataset.pickerClear]);return;}
 const more=target.closest('[data-picker-more]');if(more){const key=more.dataset.pickerMore;pickerLimits.set(key,(pickerLimits.get(key)||60)+60);renderPicker(key);return;}
 if(openFilter&&!target.closest('.filter-control'))closePicker();
 const matrix=target.closest('[data-matrix-scope]');if(matrix){mutate(()=>{clearState();state.view='developer';state.filters.surface_scope=[matrix.dataset.matrixScope];if(matrix.dataset.matrixImpact)state.filters.impact_types=[matrix.dataset.matrixImpact];});goTo('worklist');return;}
 const chart=target.closest('[data-chart-key]');if(chart){const key=chart.dataset.chartKey,value=chart.dataset.chartValue;if(chart.dataset.chartGlobal==='true')singleFilter(key,value);else mutate(()=>{const vs=state.filters[key]||[];const next=vs.includes(value)?vs.filter(v=>v!==value):[...vs,value];if(next.length)state.filters[key]=next;else delete state.filters[key];});return;}
 const q=target.closest('[data-queue]');if(q){mutate(()=>{const value=state.queue===q.dataset.queue?'':q.dataset.queue;clearState();state.queue=value;state.view=q.dataset.queue.startsWith('closure')?'closure':'developer';if(state.view==='closure'){state.sort='closure-priority';$('sort').value=state.sort;}});goTo('worklist');return;}
 const quality=target.closest('[data-quality]');if(quality){const q=qualityDefs.find(x=>x.id===quality.dataset.quality);singleFilter(...q.filter);return;}
 const scope=target.closest('[data-scope]');if(scope){mutate(()=>{clearState();state.view='developer';state.filters.surface_scope=[scope.dataset.scope];if(scope.dataset.measure==='old')state.filters.age_bucket=['181-365','>365'];if(scope.dataset.measure==='unassigned')state.filters.assignees=['__empty__'];if(scope.dataset.measure==='openpr')state.filters.repair_pr_status=['明确关闭引用 PR 进行中'];});goTo('worklist');return;}
 if(target.closest('[data-remove-queue]')){mutate(()=>state.queue='');return;}
 if(target.closest('[data-remove-search]')){mutate(()=>{state.query='';$('search').value='';});return;}
 const chip=target.closest('[data-remove-key]');if(chip){mutate(()=>{const key=chip.dataset.removeKey;state.filters[key]=state.filters[key].filter(v=>v!==chip.dataset.removeValue);if(!state.filters[key].length)delete state.filters[key];});return;}
 const issue=target.closest('[data-issue]');if(issue){showIssue(issue.dataset.issue);return;}
 const copyIssue=target.closest('[data-copy-issue]');if(copyIssue){copyText('#'+copyIssue.dataset.copyIssue);return;}
 const copy=target.closest('[data-copy-detail]');if(copy){const r=rowById.get(currentDetail),detail=getDetail(currentDetail);const choices={title:r.title,test:r.test_paths||'未提取到测试入口',source:r.source_paths||'未提取到源码路径',commands:detail.repro_commands,excerpt:detail.repro_code_excerpt,body:detail.body_markdown||detail.body_text,code:detail.repro_code_blocks?.[Number(copy.dataset.codeIndex)]};copyText(choices[copy.dataset.copyDetail]||'未提供');}
});
document.addEventListener('input',event=>{const key=event.target.dataset.pickerSearch;if(key){pickerQueries.set(key,event.target.value);pickerLimits.set(key,60);renderPicker(key);}});
document.addEventListener('change',event=>{const key=event.target.dataset.optionKey;if(!key)return;const value=event.target.dataset.optionValue;mutate(()=>{const vs=state.filters[key]||[];const next=event.target.checked?[...new Set([...vs,value])]:vs.filter(v=>v!==value);if(next.length)state.filters[key]=next;else delete state.filters[key];});});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&openFilter){event.preventDefault();event.stopPropagation();closePicker(true);}});
$('search').addEventListener('input',()=>{clearTimeout(searchTimer);const value=$('search').value.trim();searchTimer=setTimeout(()=>{const now=Date.now(),mode=now-lastSearchAt<1200?'replace':'push';lastSearchAt=now;mutate(()=>state.query=value,{mode,remember:mode==='push'});},160);});
$('reset').addEventListener('click',()=>{closePicker();mutate(clearState);});
$('undo').addEventListener('click',()=>{clearTimeout(searchTimer);const previous=undoStack.pop();if(!previous)return;Object.assign(state,previous);$('search').value=state.query;$('sort').value=state.sort;$('pageSize').value=String(state.size);render();persist('push');});
$('sort').addEventListener('change',()=>mutate(()=>state.sort=$('sort').value));
$('pageSize').addEventListener('change',()=>{savePreference('size',$('pageSize').value);mutate(()=>state.size=Number($('pageSize').value));});
$('prev').addEventListener('click',()=>mutate(()=>state.page--,{resetPage:false}));$('next').addEventListener('click',()=>mutate(()=>state.page++,{resetPage:false}));
$('share').addEventListener('click',async()=>{flushSearch();persist('replace');if(await copyText(location.href))setStatus('已复制当前筛选链接；打开后恢复多选、搜索、排序和页码。');});
$('export').addEventListener('click',exportCSV);
$('collapseOverview').addEventListener('click',()=>{$('overview').open=false;$('impactMatrix').open=false;goTo('worklist');});
$('matrixMode').addEventListener('change',renderMatrix);
$('impactMatrix').addEventListener('toggle',()=>{if($('impactMatrix').open&&!matrixRendered)renderMatrix();});
$('extraOverview').addEventListener('toggle',()=>{if($('extraOverview').open)renderExtra();});
$('scopePanel').addEventListener('toggle',()=>{if($('scopePanel').open&&!scopeRendered)renderScopes();});
$('filteredCharts').addEventListener('toggle',()=>renderFilteredCharts(compute()));
$('closeCopy').addEventListener('click',()=>$('copyDialog').close());
for(const id of ['overview','impactMatrix','extraOverview','scopePanel'])$(id).addEventListener('toggle',()=>savePreference('panels',JSON.stringify(Object.fromEntries(['overview','impactMatrix','extraOverview','scopePanel'].map(key=>[key,$(key).open])))));
$('closeDialog').addEventListener('click',()=>$('issueDialog').close());
$('issueDialog').addEventListener('click',event=>{if(event.target===$('issueDialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
function onLocation(){if(location.hash===lastHash)return;closePicker();rememberState(snapshotState());restore();render();persist('replace');}
window.addEventListener('popstate',onLocation);window.addEventListener('hashchange',onLocation);
init();
